<?php
require_once '../config/database.php';require_once '../config/auth.php';require_once '../eventos/helpers.php';require_once '../pedidos/helpers.php';
$u=requireAuth();requireCsrf();if(!usuarioTemAcessoEmpresa($conn,$u['id'],1,$u['perfil']))jsonResponse(false,'Sem acesso.',[],403);$in=readJson();$id=(int)($in['pagamento_id']??0);$status=strtoupper(trim($in['status']??''));$permit=['APROVADO','RECUSADO','CANCELADO','ESTORNADO'];if(!$id||!in_array($status,$permit,true))jsonResponse(false,'Dados inválidos.',[],400);
$conn->begin_transaction();try{$s=$conn->prepare('SELECT * FROM pagamentos WHERE id=? AND empresa_id=1 FOR UPDATE');$s->bind_param('i',$id);$s->execute();$pg=$s->get_result()->fetch_assoc();if(!$pg)throw new RuntimeException('Pagamento não encontrado.');if($pg['status']===$status){$conn->commit();jsonResponse(true,'Status já aplicado.');}$paid=$status==='APROVADO'?'NOW()':'NULL';$x=$conn->prepare("UPDATE pagamentos SET status=?,pago_em=$paid WHERE id=?");$x->bind_param('si',$status,$id);$x->execute();if(!empty($pg['pedido_id'])){$pedido=(int)$pg['pedido_id'];if($status==='APROVADO')confirmarReservaPedido($conn,$pedido);elseif(in_array($status,['CANCELADO','RECUSADO'],true)){liberarReservaPedido($conn,$pedido,'Pagamento '.$status);$x=$conn->prepare("UPDATE pedidos SET status='CANCELADO' WHERE id=?");$x->bind_param('i',$pedido);$x->execute();}}
$prio=$status==='APROVADO'?'ATENCAO':'INFORMATIVO';criarEventoENotificar($conn,1,$u['id'],'Pagamento '.$status,'Pagamento #'.$id.' alterado para '.$status.'.',$prio,'PAGAMENTO',$id,'PAGAMENTO_STATUS:'.$id.':'.$status,'PAGAMENTOS','PAGAMENTO_'.$status);registrarAuditoria($conn,$u['id'],1,'ALTERAR_PAGAMENTO','PAGAMENTO',$id,$status);enfileirarSheets($conn,1,'PAGAMENTO','PAGAMENTO',$id);if(!empty($pg['pedido_id']))enfileirarSheets($conn,1,'PEDIDO','PEDIDO',(int)$pg['pedido_id']);$conn->commit();jsonResponse(true,'Status atualizado.');}catch(Throwable $e){$conn->rollback();jsonResponse(false,$e->getMessage(),[],400);}
